END check_attachment_length_CN;
PROCEDURE delete_duplicate_attachment (
    p_ext_doc_id IN  VARCHAR2,
    output       OUT NUMBER)
     As

BEGIN
 -- delete duplicate Lines

DELETE FROM ktn_ar_attachemnts_stg WHERE ROWID IN(SELECT TEMP.ROWID FROM(
SELECT ROWID,ATTACHMENT_TYPE, EXT_DOC_NUMBER, LINE_NUMBER,DESCRIPTION,DESCRIPTIONN,PROCESS_FLAG,
ROW_NUMBER()OVER (PARTITION BY line_number ORDER BY ROWID DESC) RN  FROM ktn_ar_attachemnts_stg where ext_doc_number=p_ext_doc_id and attachment_type='LINE'
)TEMP
WHERE TEMP.RN <> 1 AND ext_doc_number=p_ext_doc_id);

-- delete duplicate Header

DELETE FROM ktn_ar_attachemnts_stg WHERE ROWID IN(SELECT TEMP.ROWID FROM(
SELECT ROWID,ATTACHMENT_TYPE, EXT_DOC_NUMBER, LINE_NUMBER,DESCRIPTION,DESCRIPTIONN,PROCESS_FLAG,
ROW_NUMBER()OVER (PARTITION BY to_char(descriptionn) ORDER BY ROWID DESC) RN  FROM ktn_ar_attachemnts_stg where ext_doc_number=p_ext_doc_id and attachment_type='HEADER'
)TEMP
WHERE TEMP.RN <> 1 AND ext_doc_number=p_ext_doc_id);

--
-- delete duplicate URL

---- test

DELETE FROM ktn_ar_attachemnts_stg WHERE ROWID IN(SELECT TEMP.ROWID FROM(
SELECT ROWID,ATTACHMENT_TYPE, EXT_DOC_NUMBER, LINE_NUMBER,DESCRIPTION,DESCRIPTIONN,PROCESS_FLAG,
ROW_NUMBER()OVER (PARTITION BY to_char(descriptionn) ORDER BY ROWID DESC) RN  FROM ktn_ar_attachemnts_stg where ext_doc_number=p_ext_doc_id and attachment_type='URL'
)TEMP
WHERE TEMP.RN <> 1 AND ext_doc_number=p_ext_doc_id);

-- update process flag
UPDATE ktn_ar_attachemnts_stg
SET PROCESS_FLAG=null
WHERE EXT_DOC_NUMBER=p_ext_doc_id;
output:=0;
END delete_duplicate_attachment;
END KTN_AR_ATTACHMENTS_UTILS_PKG;
/
